    @EventHandler( payloadType=CreateOpportunityEvent.class )
    public void handle( CreateOpportunityEvent event) {
	    LOGGER.info("handling CreateOpportunityEvent - " + event );
	    Opportunity entity = new Opportunity();
            entity.setOpportunityId( event.getOpportunityId() );
            entity.setName( event.getName() );
            entity.setAmount( event.getAmount() );
            entity.setCloseDate( event.getCloseDate() );
            entity.setProbability( event.getProbability() );
            entity.setDescription( event.getDescription() );
            entity.setStage( event.getStage() );
            entity.setType( event.getType() );
            entity.setForecastCategory( event.getForecastCategory() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllOpportunity( entity );
    }

