    /**
     * Method to retrieve the Opportunity via an OpportunityPrimaryKey.
     * @param 	id Long
     * @return 	Opportunity
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Opportunity handle( FindOpportunityQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getOpportunityId() );
    }
    
    /**
     * Method to retrieve a collection of all Opportunitys
     *
     * @param	query	FindAllOpportunityQuery 
     * @return 	List<Opportunity> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Opportunity> handle( FindAllOpportunityQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindOpportunity,
 * but only if the id matches
 *
 * @param		entity	Opportunity
 */
	protected void emitFindOpportunity( Opportunity entity ) {
		LOGGER.info("handling emitFindOpportunity" );
		
	    queryUpdateEmitter.emit(FindOpportunityQuery.class,
	                            query -> query.getFilter().getOpportunityId().equals(entity.getOpportunityId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllOpportunity
	 * 
	 * @param		entity	Opportunity
	 */
	protected void emitFindAllOpportunity( Opportunity entity ) {
		LOGGER.info("handling emitFindAllOpportunity" );
		
	    queryUpdateEmitter.emit(FindAllOpportunityQuery.class,
	                            query -> true,
	                            entity);
	}

